15	async function runQuery(prompt: string, cwd: string, maxTurns: number): Promise<string> {
16	  const stream = query({
17	    prompt,
18	    options: { ...READ_ONLY_OPTIONS, cwd, maxTurns }
19	  });
20	
21	  let resultText = '';
22	  for await (const message of stream) {
23	    const anyMessage = message as { type?: string; subtype?: string; result?: string };
24	    if (anyMessage.type === 'result') {
25	      if (anyMessage.subtype && anyMessage.subtype !== 'success') {
26	        throw new Error(`Agent run ended without success (${anyMessage.subtype}).`);
27	      }
28	      resultText = anyMessage.result ?? '';
29	    }
30	  }
31	  return resultText;
32	}
