68	function extractTier(body: string): RiskTier | null {
69	  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
70	  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
71	  const fieldLine = body
72	    .split(/\r?\n/)
73	    .find((l) => /\*\*tier\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l));
74	  const haystacks = fieldLine ? [fieldLine] : [body];
75	  for (const text of haystacks) {
76	    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
77	    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
78	    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
79	    if (found.length === 1) return found[0];
80	    if (found.length > 1) {
81	      // Ambiguous mention; prefer the value after a colon on the field line.
82	      const afterColon = cleaned.split(':').slice(1).join(':');
83	      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
84	      if (inValue.length === 1) return inValue[0];
85	    }
86	  }
87	  return null;
88	}
89	
90	function answeredText(body: string): string {
91	  return body
92	    .split(/\r?\n/)
93	    .filter((l) => !EMPTY_FIELD.test(l))
94	    .join('\n')
95	    .trim();
96	}
