6	const SECRETS_GUARD = `Never read, quote, or summarize secret material: skip .env and .env.* files, private keys and certificates (id_*, *.pem, *.key, *.p12), credential stores, token caches, and anything under a secrets/ or credentials/ directory. If a gate answer would require their contents, write "NEEDS HUMAN INPUT" instead.`;
7	
8	const READ_ONLY_OPTIONS = {
9	  allowedTools: ['Read', 'Glob', 'Grep'],
10	  disallowedTools: ['Write', 'Edit', 'NotebookEdit', 'Bash', 'WebFetch', 'WebSearch', 'Task'],
11	  permissionMode: 'bypassPermissions' as const,
12	  model: DEFAULT_MODEL
13	};
