34	function between(text: string, begin: string, end: string): string | null {
35	  const start = text.indexOf(begin);
36	  if (start === -1) return null;
37	  const stop = text.indexOf(end, start + begin.length);
38	  if (stop === -1) return null;
39	  return text.slice(start + begin.length, stop).trim();
40	}
