79	/**
80	 * Adversarially reviews an already-valid gate section for quality: vague answers,
81	 * untestable claims, thresholds that don't match the code. Returns extra findings.
82	 */
83	export async function smartReview(specMarkdown: string, cwd: string): Promise<Finding[]> {
84	  const prompt = `You are FRAI's Responsible AI Gate reviewer. Below is a spec containing a "## Responsible AI Gate" section. Adversarially review ONLY the gate answers for quality. You may Read/Glob/Grep this repository to verify claims against the code.
85	
86	${SECRETS_GUARD}
87	
88	Flag (severity "warn" unless truly disqualifying, then "block"):
89	- Vague or unfalsifiable answers ("we take privacy seriously", "monitor closely")
90	- Metrics without thresholds, thresholds without datasets, owners that are teams instead of people
91	- Gate answers contradicted by the code (e.g. spec says "no PII" but code logs emails)
92	- A risk tier that is too low for what the feature actually does
93	
94	Do NOT flag style, formatting, or sections outside the gate. If everything is solid, return an empty list.
95	
96	Output ONLY JSON between these exact markers (checkId one of: risk-tier, data-privacy, oversight, evaluation, bias, monitoring, transparency):
97	<!-- RAI-FINDINGS:BEGIN -->
98	[{"checkId": "...", "severity": "warn", "message": "..."}]
99	<!-- RAI-FINDINGS:END -->
100	
101	SPEC:
102	${specMarkdown}`;
103	
104	  const result = await runQuery(prompt, cwd, 30);
105	  const json = between(result, '<!-- RAI-FINDINGS:BEGIN -->', '<!-- RAI-FINDINGS:END -->');
106	  if (json === null) throw new Error(`Reviewer did not return findings JSON. Raw output:\n${result}`);
107	  const parsed = JSON.parse(json) as Array<Omit<Finding, 'source'>>;
108	  return parsed.map((f) => ({
109	    checkId: String(f.checkId ?? 'gate'),
110	    severity: f.severity === 'block' ? 'block' : 'warn',
111	    message: String(f.message ?? ''),
112	    source: 'agent' as const
113	  }));
114	}
