import { describe, expect, it } from 'vitest';
import { renderSummary } from './report.js';
import { GateResult } from './schema.js';

describe('renderSummary', () => {
  it('returns PASS 7/7 when all checks answered', () => {
    const result: GateResult = {
      verdict: 'PASS',
      tier: 'minimal',
      findings: [],
      gateSection: 'some content'
    };
    expect(renderSummary(result)).toBe('PASS 7/7');
  });

  it('returns WARN with full answered count when no blocks', () => {
    const result: GateResult = {
      verdict: 'WARN',
      tier: 'limited',
      findings: [
        {
          checkId: 'data-privacy',
          severity: 'warn',
          message: 'Needs more detail',
          source: 'validator'
        }
      ],
      gateSection: 'some content'
    };
    expect(renderSummary(result)).toBe('WARN 7/7');
  });

  it('returns BLOCK with single check when one check has block', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'bias',
          severity: 'block',
          message: 'Missing bias mitigation section',
          source: 'validator'
        }
      ],
      gateSection: 'some content'
    };
    expect(renderSummary(result)).toBe('BLOCK 6/7: bias');
  });

  it('returns BLOCK with multiple checks in GATE_CHECKS order', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'transparency',
          severity: 'block',
          message: 'Missing transparency section',
          source: 'validator'
        },
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Missing evaluation plan',
          source: 'validator'
        }
      ],
      gateSection: 'some content'
    };
    expect(renderSummary(result)).toBe('BLOCK 5/7: evaluation, transparency');
  });

  it('returns BLOCK 0/7: structure when gate section missing', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'structure',
          severity: 'block',
          message: 'No gate section found',
          source: 'validator'
        }
      ],
      gateSection: null
    };
    expect(renderSummary(result)).toBe('BLOCK 0/7: structure');
  });

  it('shows structure first in block list when present', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'structure',
          severity: 'block',
          message: 'No gate section found',
          source: 'validator'
        },
        {
          checkId: 'bias',
          severity: 'block',
          message: 'Missing bias section',
          source: 'validator'
        }
      ],
      gateSection: null
    };
    expect(renderSummary(result)).toBe('BLOCK 0/7: structure, bias');
  });

  it('handles duplicate check IDs in findings (counts unique only once)', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'bias',
          severity: 'block',
          message: 'No disparate impact analysis',
          source: 'validator'
        },
        {
          checkId: 'bias',
          severity: 'block',
          message: 'Mitigation strategy missing',
          source: 'agent'
        }
      ],
      gateSection: 'some content'
    };
    expect(renderSummary(result)).toBe('BLOCK 6/7: bias');
  });

  it('ignores warn-severity findings when counting blocks', () => {
    const result: GateResult = {
      verdict: 'WARN',
      tier: 'limited',
      findings: [
        {
          checkId: 'bias',
          severity: 'warn',
          message: 'No numeric threshold',
          source: 'validator'
        },
        {
          checkId: 'monitoring',
          severity: 'block',
          message: 'Missing rollback procedure',
          source: 'validator'
        }
      ],
      gateSection: 'some content'
    };
    expect(renderSummary(result)).toBe('WARN 6/7: monitoring');
  });

  it('handles all seven checks with blocks correctly', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'risk-tier',
          severity: 'block',
          message: 'Missing tier',
          source: 'validator'
        },
        {
          checkId: 'data-privacy',
          severity: 'block',
          message: 'Missing privacy section',
          source: 'validator'
        },
        {
          checkId: 'oversight',
          severity: 'block',
          message: 'Missing oversight',
          source: 'validator'
        },
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Missing evaluation',
          source: 'validator'
        },
        {
          checkId: 'bias',
          severity: 'block',
          message: 'Missing bias mitigation',
          source: 'validator'
        },
        {
          checkId: 'monitoring',
          severity: 'block',
          message: 'Missing monitoring',
          source: 'validator'
        },
        {
          checkId: 'transparency',
          severity: 'block',
          message: 'Missing transparency',
          source: 'validator'
        }
      ],
      gateSection: 'some content'
    };
    expect(renderSummary(result)).toBe('BLOCK 0/7: risk-tier, data-privacy, oversight, evaluation, bias, monitoring, transparency');
  });

  it('handles mixed warn and block on same check', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
